@rendermode InteractiveServer
@using System.ComponentModel.DataAnnotations
@using sv_f227c074230246e59e9fb369638fd795.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Appointment Requested!</h4>
        <p>Thank you, <strong>@_model.PatientName</strong>. Your appointment with <strong>@_model.Doctor</strong>
            on <strong>@_model.AppointmentDate?.ToString("MMM dd, yyyy")</strong> at <strong>@_model.TimeSlot</strong>
            has been submitted.</p>
        <button class="btn btn-primary mt-2" @onclick="Reset">Book Another</button>
    </div>
}
else
{
    <EditForm EditContext="_editContext" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
        <DataAnnotationsValidator />

        @* ───── STEP 1: Patient Information ───── *@
        <fieldset class="border rounded p-3 mb-4">
            <legend class="w-auto px-2 fs-5">Step 1 — Patient Information</legend>

            <div class="mb-3">
                <label class="form-label" for="patientName">Patient Name</label>
                <InputText id="patientName" class="form-control" @bind-Value="_model.PatientName" />
                <ValidationMessage For="() => _model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <InputText id="email" class="form-control" @bind-Value="_model.Email" />
                <ValidationMessage For="() => _model.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="phone">Phone</label>
                <InputText id="phone" class="form-control" @bind-Value="_model.Phone" />
                <ValidationMessage For="() => _model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="insurance">Insurance Provider</label>
                <InputSelect id="insurance" class="form-select" @bind-Value="_model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => _model.InsuranceProvider" />
            </div>
        </fieldset>

        @if (!_showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next &rarr;
            </button>
        }

        @* ───── STEP 2: Appointment Details ───── *@
        @if (_showStep2)
        {
            <fieldset class="border rounded p-3 mb-4">
                <legend class="w-auto px-2 fs-5">Step 2 — Appointment Details</legend>

                <div class="mb-3">
                    <label class="form-label" for="doctor">Preferred Doctor</label>
                    <InputSelect id="doctor" class="form-select" @bind-Value="_model.Doctor"
                        @bind-Value:after="OnDoctorChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in _doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _model.Doctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="appointmentDate">Date</label>
                    <InputDate id="appointmentDate" class="form-control" @bind-Value="_model.AppointmentDate"
                        @bind-Value:after="OnDateChanged" />
                    <ValidationMessage For="() => _model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="timeSlot">Time Slot</label>
                    <InputSelect id="timeSlot" class="form-select" @bind-Value="_model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in _availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _model.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="reason">Reason for Visit</label>
                    <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="_model.ReasonForVisit" />
                    <ValidationMessage For="() => _model.ReasonForVisit" />
                </div>

                <div class="d-flex gap-2">
                    <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">
                        &larr; Back
                    </button>
                    <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@_checking">
                        @(_checking ? "Checking…" : "Check Availability")
                    </button>
                    <button type="submit" class="btn btn-success" disabled="@(!_availabilityChecked)">
                        Submit Appointment
                    </button>
                </div>
            </fieldset>
        }
    </EditForm>
}

@code {
    private AppointmentModel _model = new();
    private EditContext _editContext = null!;
    private ValidationMessageStore _messageStore = null!;

    private bool _showStep2;
    private bool _submitted;
    private bool _checking;
    private bool _availabilityChecked;

    private List<string> _doctors = [];
    private List<string> _availableSlots = [];

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override void OnInitialized()
    {
        _editContext = new EditContext(_model);
        _messageStore = new ValidationMessageStore(_editContext);
        _editContext.OnFieldChanged += (_, args) =>
        {
            // Clear server errors for the field the user just edited
            _messageStore.Clear(args.FieldIdentifier);
            _availabilityChecked = false;
        };
    }

    private void ProceedToStep2()
    {
        // Validate only step-1 fields
        _messageStore.Clear();
        var isValid = _editContext.Validate();

        if (!isValid)
        {
            // If step-2 fields have errors, they're irrelevant at this point;
            // check whether any step-1 field has messages.
            var step1HasErrors = Step1Fields.Any(f =>
                _editContext.GetValidationMessages(new FieldIdentifier(_model, f)).Any());

            if (step1HasErrors)
                return;
        }

        _showStep2 = true;
        _ = LoadDoctorsAsync();
    }

    private async Task LoadDoctorsAsync()
    {
        _doctors = await AppointmentSvc.GetDoctorsAsync();
        StateHasChanged();
    }

    private async Task OnDoctorChanged()
    {
        _availabilityChecked = false;
        await RefreshSlots();
    }

    private async Task OnDateChanged()
    {
        _availabilityChecked = false;
        await RefreshSlots();
    }

    private async Task RefreshSlots()
    {
        _model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(_model.Doctor) && _model.AppointmentDate.HasValue)
        {
            _availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                _model.Doctor, DateOnly.FromDateTime(_model.AppointmentDate.Value));
        }
        else
        {
            _availableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        _messageStore.Clear();
        _availabilityChecked = false;

        if (!_editContext.Validate())
            return;

        _checking = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                _model.Email, _model.InsuranceProvider, _model.Doctor!, _model.TimeSlot!);

            if (errors.Count > 0)
            {
                foreach (var (field, message) in errors)
                {
                    _messageStore.Add(new FieldIdentifier(_model, field), message);
                }
                _editContext.NotifyValidationStateChanged();
                return;
            }

            _availabilityChecked = true;
        }
        finally
        {
            _checking = false;
        }
    }

    private void BackToStep1()
    {
        _showStep2 = false;
        _availabilityChecked = false;
    }

    private void HandleSubmit()
    {
        if (!_availabilityChecked) return;
        _submitted = true;
    }

    private void Reset()
    {
        _model = new();
        _editContext = new EditContext(_model);
        _messageStore = new ValidationMessageStore(_editContext);
        _editContext.OnFieldChanged += (_, args) =>
        {
            _messageStore.Clear(args.FieldIdentifier);
            _availabilityChecked = false;
        };
        _showStep2 = false;
        _submitted = false;
        _availabilityChecked = false;
        _availableSlots = [];
    }

    // ── Form model with DataAnnotations ──
    private sealed class AppointmentModel
    {
        [Required(ErrorMessage = "Patient name is required.")]
        public string PatientName { get; set; } = string.Empty;

        [Required(ErrorMessage = "Email is required.")]
        [EmailAddress(ErrorMessage = "Enter a valid email address.")]
        public string Email { get; set; } = string.Empty;

        [Required(ErrorMessage = "Phone number is required.")]
        [Phone(ErrorMessage = "Enter a valid phone number.")]
        public string Phone { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select an insurance provider.")]
        public string InsuranceProvider { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a doctor.")]
        public string? Doctor { get; set; }

        [Required(ErrorMessage = "Appointment date is required.")]
        [FutureDate(ErrorMessage = "Date must be in the future.")]
        public DateTime? AppointmentDate { get; set; }

        [Required(ErrorMessage = "Please select a time slot.")]
        public string? TimeSlot { get; set; }

        [Required(ErrorMessage = "Reason for visit is required.")]
        [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
        public string? ReasonForVisit { get; set; }
    }

    private sealed class FutureDateAttribute : ValidationAttribute
    {
        protected override ValidationResult? IsValid(object? value, ValidationContext context)
        {
            if (value is DateTime dt && dt.Date <= DateTime.Today)
                return new ValidationResult(ErrorMessage);
            return ValidationResult.Success;
        }
    }
}

